#include <Wire.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);

void setup() {
  Wire.begin({{sda_pin}}, {{scl_pin}});
  oled.begin(SSD1306_SWITCHCAPVCC, {{oled_addr}});
  oled.clearDisplay();
  oled.setTextSize(2);
  oled.setTextColor(SSD1306_WHITE);
  oled.setCursor(0, 20);
  oled.print("{{text}}");
  oled.display();
}

void loop() {}
